// Otomatik bitki sulama: toprak kuruyunca pompayı 5 saniye çalıştır.
const int NEM_PIN = 34;                     // toprak nem sensörü AO
const int ROLE_PIN = 26;                    // röle modülü IN
const int KURU_ESIK = 2500;                 // bunun üstü "kuru". Seri ekrandaki değere göre ayarla.
const unsigned long SULAMA_MS = 5000;       // pompa çalışma süresi
const unsigned long BEKLEME_MS = 60000UL;   // iki sulama arası en az 1 dakika

// Çoğu röle modülü LOW ile çeker. Seninki HIGH ile çekiyorsa bu iki satırı değiştir.
const int ROLE_ACIK = LOW;
const int ROLE_KAPALI = HIGH;

unsigned long sonSulama = 0;
bool hicSulanmadi = true;

void setup() {
  Serial.begin(115200);
  pinMode(ROLE_PIN, OUTPUT);
  digitalWrite(ROLE_PIN, ROLE_KAPALI);
}

void loop() {
  int nem = analogRead(NEM_PIN);  // 0-4095. Kapasitif sensörde kuru toprak = yüksek değer.
  Serial.printf("Nem okumasi: %d\n", nem);

  bool kuru = nem > KURU_ESIK;
  bool beklemeBitti = hicSulanmadi || millis() - sonSulama > BEKLEME_MS;

  if (kuru && beklemeBitti) {
    Serial.println("Toprak kuru: pompa calisiyor.");
    digitalWrite(ROLE_PIN, ROLE_ACIK);
    delay(SULAMA_MS);
    digitalWrite(ROLE_PIN, ROLE_KAPALI);
    sonSulama = millis();
    hicSulanmadi = false;
  }
  delay(1000);
}
